// while its account has no sandbox free, "generating" again once it has
// one. Only over a run still running: a job asked to stop keeps
// `cancelling`, and an ended one its ending.
// And only by the attempt that is running: a process that lost its job to a
// re-queue does not write over the phase of the attempt that replaced it.
func (q *Queries) SetRunningPhase(ctx context.Context, arg SetRunningPhaseParams) error {
	_, err := q.db.Exec(ctx, setRunningPhase,
		arg.Phase,
		arg.Now,
		arg.ID,
		arg.UserID,
		arg.Attempt,
	)
	return err
}

const sourceDocuments = `-- name: SourceDocuments :many
SELECT id, title, COALESCE(NULLIF(source_markdown, ''), content) AS body
FROM documents
WHERE user_id = $1
  AND (id = ANY($2::bigint[]) OR folder_id = ANY($3::bigint[]))
  AND status ->> 'state' <> 'deleting'
ORDER BY id
LIMIT $4
`

type SourceDocumentsParams struct {
	UserID      string
	DocumentIds []int64
	FolderIds   []int64
	Most        int32
}

type SourceDocumentsRow struct {
	ID    int64
	Title string
	Body  string
}

// The documents those sources reach: each named document and every document
// directly in a named folder, the caller's own, in a stable order. One being
// deleted is left out: its text is on its way out of the account.
func (q *Queries) SourceDocuments(ctx context.Context, arg SourceDocumentsParams) ([]SourceDocumentsRow, error) {
	rows, err := q.db.Query(ctx, sourceDocuments,
		arg.UserID,
		arg.DocumentIds,
		arg.FolderIds,
		arg.Most,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SourceDocumentsRow
	for rows.Next() {
		var i SourceDocumentsRow
		if err := rows.Scan(&i.ID, &i.Title, &i.Body); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const storeSuggestionPool = `-- name: StoreSuggestionPool :exec
UPDATE notebooks SET
    focus_suggestions = CASE WHEN focus_suggestions_key = $1 AND jsonb_typeof(focus_suggestions) = 'object'
                             THEN focus_suggestions ELSE '{}'::jsonb END
                        || jsonb_build_object($2::text, $3::jsonb),
    focus_suggestions_key = $1
WHERE id = $4 AND user_id = $5
`

type StoreSuggestionPoolParams struct {
	SourcesKey *string
	PoolKey    string
	Pool       []byte
	NotebookID int64
	UserID     string
}

// One pool, kept beside the others written for the same source set. A pool
// written for a different source set replaces the whole cache: its ideas
// name things the notebook may no longer hold.
func (q *Queries) StoreSuggestionPool(ctx context.Context, arg StoreSuggestionPoolParams) error {
	_, err := q.db.Exec(ctx, storeSuggestionPool,
		arg.SourcesKey,
		arg.PoolKey,
		arg.Pool,
		arg.NotebookID,
		arg.UserID,
	)
	return err
}

const suggestionCache = `-- name: SuggestionCache :one
SELECT focus_suggestions, focus_suggestions_key FROM notebooks
WHERE id = $1 AND user_id = $2
`

type SuggestionCacheParams struct {
	NotebookID int64
	UserID     string
}

type SuggestionCacheRow struct {
	FocusSuggestions    []byte
	FocusSuggestionsKey *string
}

// The notebook's cached suggestion pools and the source set they were
// written for.
func (q *Queries) SuggestionCache(ctx context.Context, arg SuggestionCacheParams) (SuggestionCacheRow, error) {
	row := q.db.QueryRow(ctx, suggestionCache, arg.NotebookID, arg.UserID)
	var i SuggestionCacheRow
	err := row.Scan(&i.FocusSuggestions, &i.FocusSuggestionsKey)
	return i, err
}

const unfinishedArtifactJobs = `-- name: UnfinishedArtifactJobs :one
SELECT count(*) FROM deliverable_jobs
WHERE user_id = $1 AND kind = 'artifact' AND status IN ('queued', 'running', 'cancelling')
`

// How many of the account's artifact jobs are waiting or being made: what
// the per-account limit at the generate route counts.
func (q *Queries) UnfinishedArtifactJobs(ctx context.Context, userID string) (int64, error) {
	row := q.db.QueryRow(ctx, unfinishedArtifactJobs, userID)
	var count int64
	err := row.Scan(&count)
	return count, err
}
